const req = $json;
const body = req.body ?? req;
const required = ['tenant_id','workflow_id','invocation_id','idempotency_key','schema_version'];
for (const key of required) {
  if (!body[key]) throw new Error(`Missing ${key}`);
}
if (!String(body.schema_version).startsWith('2.')) throw new Error('Unsupported Jahorin n8n schema');
return [{
  json: {
    ...body,
    received_at: new Date().toISOString(),
    phase: 'acting',
    input: body.input ?? {},
    memory_context: Array.isArray(body.memory_context) ? body.memory_context : [],
  }
}];

const a=$json.approval;
if (!a || !['approved','consumed'].includes(String(a.status))) throw new Error('TAE approval receipt required');
const input=$json.input??{};
if (!input.to || !input.subject || !input.body) throw new Error('Email to, subject and body are required');
return [{json:{...$json,to:String(input.to),subject:String(input.subject),body:String(input.body)}}];

const sent=$json;
const source=$('Validate Human Approval').first().json;
const messageId=sent.id ?? sent.messageId ?? sent.threadId ?? null;
return [{json:{
  workflow_id: source.workflow_id,
  status:'completed',
  result:{message_id:messageId,thread_id:sent.threadId??null},
  evidence:[{kind:'email_sent',source:'gmail',at:new Date().toISOString(),message_id:messageId}],
}}];
